import React from 'react'
import {Container, Row, Col} from 'react-bootstrap'
import {Link} from 'react-router-dom'
 
function Train({train_number, train_name, from_sta, from_std, train_date, to_station_name, ...rest}) {
  return (
    <Link to='/train/details' style={{backgroundColor: 'grey', height: '25', textDecoration: 'none', color: 'white'}}>
      <Container>
        <Row>
            <Col md={2}>
                Train number : {train_number}
            </Col>
            <Col md={2}>
                Train name : {train_name}
            </Col>
            <Col md={2}>
                Date : {train_date}
            </Col>
            <Col md={2}>
                arrival : {from_sta}
            </Col>            
            <Col md={2}>
                departure : {from_std}
            </Col>
            <Col md={2}>
                last station : {to_station_name}
            </Col>
        </Row>
      </Container>
    </Link>
  )
}

export default Train
